export function generateMaze(width: number, height: number): number[][] {
    const maze: number[][] = Array.from({ length: height }, () => Array(width).fill(0));
    const directions = [[0, -1], [0, 1], [-1, 0], [1, 0]];
    const stack: number[][] = [[0, 0]];
    maze[0][0] = 1;
    const backtrackingStack: number[][] = [[0, 0]];
    const visited: boolean[][] = Array.from({ length: height }, () => Array(width).fill(false));
    const backtrack: number[][] = [];
    const walls: number[][] = [];
    let cellsVisited = 1;
    let backtrackIndex = 0;

    const carvePath = (x: number, y: number) => {
        visited[y][x] = true;
        const directionsCopy = [...directions];
        if (backtrackIndex > 0) {
            const prev = backtrack[backtrackIndex - 1];
            const dx = x - prev[0];
            const dy = y - prev[1];
            directionsCopy.push([-dx, -dy]);
        }
        backtrackIndex = backtrack.length;
        backtrack.push([x, y]);
        const dirs = directionsCopy.filter(([dx2, dy2]) => x + dx2 >= 0 && x + dx2 < width && y + dy2 >= 0 && y + dy2 < height && !visited[y + dy2][x + dx2]);
        if (dirs.length === 0) {
            const last = backtrack[backtrackIndex - 1];
            maze[y + 1][x] = 1; maze[y - 1][x] = 1; maze[y][x + 1] = 1; maze[y][x - 1] = 1;
            backtrack.pop();
            backtrackIndex--;
            if (backtrack.length > 0) {
                const [bx, by] = backtrack[backtrackIndex - 1];
                stack.push([bx, by]);
                backtrackingStack.push([bx, by]);
                cellsVisited--;
            } else {
                return;
            }
        } else {
            const [dx, dy] = dirs[Math.floor(Math.random() * dirs.length)];
            const nx = x + dx; const ny = y + dy;
            maze[y + (dy + 1) / 2][x + (dx + 1) / 2] = 1;
            cellsVisited++;
            stack.push([nx, ny]);
            backtrackingStack.push([nx, ny]);
            backtrackIndex = backtrackingStack.length;
            carvePath(nx, ny);
        }
    };

    carvePath(0, 0);
    const start = [0, 0];
    const end = [width - 1, height - 1];
    maze[height - 1][width - 1] = 2;
    return { maze, start, end };
}

export function solveMaze(maze: number[][], start: number[], end: number[]): number[][] {
    const directions = [[0, -1], [0, 1], [-1, 0], [1, 0]];
    const queue: number[][] = [start];
    const visited: boolean[][] = Array.from({ length: maze.length }, () => Array(maze[0].length).fill(false));
    const path: number[][] = [];
    let found = false;

    const isValid = (x: number, y: number) => x >= 0 && x < maze[0].length && y >= 0 && y < maze.length && maze[y][x] !== 0 && !visited[y][x];

    while (queue.length > 0 && !found) {
        const [cx, cy] = queue.shift()!;
        visited[cy][cx] = true;
        path.push([cx, cy]);
        if (cx === end[0] && cy === end[1]) {
            found = true;
            break;
        }
        for (const [dx, dy] of directions) {
            const nx = cx + dx; const ny = cy + dy;
            if (isValid(nx, ny)) {
                queue.push([nx, ny]);
            }
        }
    }

    if (found) {
        const solutionPath: number[][] = [];
        let cx = end[0]; let cy = end[1];
        while (cx !== start[0] || cy !== start[1]) {
            solutionPath.push([cx, cy]);
            const last = path[path.length - 1];
            path.pop();
            cx = last[0]; cy = last[1];
        }
        solutionPath.push(start);
        return solutionPath.reverse();
    }
    return [];
}

