export function handleInput(input: string): { result: string; errors?: string[] } {
    const lines = input.split('\n');
    const mazeData: number[][] = [];
    const start: number[] = [];
    const end: number[] = [];
    let foundPath = false;
    let path: number[][] = [];

    for (let i = 0; i < lines.length; i++) {
        const cols = lines[i].split(' ').map((c) => parseInt(c));
        if (cols.length > 0) {
            if (cols.some((c) => c === 2)) {
                end = [cols.indexOf(2), i];
                cols[cols.indexOf(2)] = 0;
            }
            if (cols.some((c) => c === 1)) {
                start = [cols.indexOf(1), i];
                cols[cols.indexOf(1)] = 0;
            }
            mazeData.push(cols);
        }
    }

    if (start.length === 0 || end.length === 0) {
        return { result: 'Error: Start or end not found', errors: [] };
    }

    const directions = [[0, -1], [0, 1], [-1, 0], [1, 0]];
    const queue: number[][] = [start];
    const visited: boolean[][] = Array.from({ length: mazeData.length }, () => Array(mazeData[0].length).fill(false));
    const pathStack: number[][] = [];
    let found = false;

    const isValid = (x: number, y: number) => x >= 0 && x < mazeData[0].length && y >= 0 && y < mazeData.length && mazeData[y][x] !== 0 && !visited[y][x];

    while (queue.length > 0 && !found) {
        const [cx, cy] = queue.shift()!;
        visited[cy][cx] = true;
        pathStack.push([cx, cy]);
        if (cx === end[0] && cy === end[1]) {
            found = true;
            break;
        }
        for (const [dx, dy] of directions) {
            const nx = cx + dx; const ny = cy + dy;
            if (isValid(nx, ny)) {
                queue.push([nx, ny]);
            }
        }
    }

    if (found) {
        path = [];
        let cx = end[0]; let cy = end[1];
        while (cx !== start[0] || cy !== start[1]) {
            path.push([cx, cy]);
            const last = pathStack[pathStack.length - 1];
            pathStack.pop();
            cx = last[0]; cy = last[1];
        }
        path.push(start);
        path.reverse();
        foundPath = true;
    }

    const result = mazeData.map((row, y) => row.map((cell, x) => {
        if (cell === 2) return 'E';
        if (cell === 1) return 'S';
        if (path.some(([px, py]) => px === x && py === y)) return 'P';
        return String(cell);
    })).join('\n');

    return { result, errors: foundPath ? [] : ['Path not found'] };
}

