export class ScoreStore {
  private scores: Record<number, string>;

  constructor() {
    this.scores = {};
    this.loadScores();
  }

  loadScores(): void {
    try {
      const saved = localStorage.getItem('highscores');
      if (saved) this.scores = JSON.parse(saved);
    } catch {}
  }

  saveScore(score: number, name: string): void {
    if (score <= 0) return;
    this.scores[score] = name;
    this.saveToStorage();
  }

  saveToStorage(): void {
    try {
      localStorage.setItem('highscores', JSON.stringify(this.scores));
    } catch {}
  }

  getTopScores(): number[] {
    return Object.keys(this.scores)
      .map(Number)
      .sort((a, b) => b - a)
      .slice(0, 10);
  }

  getScoreName(score: number): string | null {
    return this.scores[score] || null;
  }
}

